const __pageData = JSON.parse('{"title":"Tucker Carlson","description":"","frontmatter":{"title":"Tucker Carlson","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["media","first-amendment","iran","fara","censorship"],"sources":["raw/badlands-brief-095.md","raw/badlands-brief-285.md","raw/badlands-brief-52f.md","raw/badlands-brief-7c6.md","raw/badlands-brief-7ed.md","raw/badlands-brief-959.md","raw/badlands-brief-d3b.md","raw/badlands-news-brief-001.md","raw/badlands-news-brief-050.md","raw/badlands-news-brief-07f.md","raw/badlands-news-brief-082.md","raw/badlands-news-brief-090.md","raw/badlands-news-brief-02f.md","raw/badlands-news-brief-0f0.md","raw/badlands-news-brief-0ef.md","raw/badlands-news-brief-11b.md","raw/badlands-news-brief-12a.md","raw/badlands-news-brief-1a7.md","raw/badlands-news-brief-1e2.md","raw/badlands-news-brief-204.md","raw/badlands-news-brief-275.md","raw/badlands-news-brief-2e7.md","raw/badlands-news-brief-2e8.md","raw/badlands-news-brief-3e5.md","raw/badlands-news-brief-46b.md","raw/badlands-news-brief-49a.md","raw/badlands-news-brief-4a3.md","raw/badlands-news-brief-525.md","raw/badlands-news-brief-582.md","raw/badlands-news-brief-60c.md","raw/badlands-news-brief-644.md","raw/badlands-news-brief-6b1.md","raw/badlands-news-brief-6af.md","raw/badlands-news-brief-6f7.md","raw/badlands-news-brief-6e5.md","raw/badlands-news-brief-72e.md","raw/badlands-news-brief-757.md","raw/badlands-news-brief-8a4.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/tucker-carlson.md","filePath":"entities/tucker-carlson.md","lastUpdated":null}');
